input.command:
cat > variables.tf <<'EOF'
variable "github_repository" {
  type        = string
  description = "GitHub repository, in owner/name form, whose workflow may assume the CI roles. Only workflow runs from this repository are trusted."
  default     = "platform/ingest"

  validation {
    condition     = can(regex("^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$", var.github_repository))
    error_message = "github_repository must be in owner/name form with no wildcards."
  }
}

variable "apply_branch" {
  type        = string
  description = "Branch whose workflow runs may assume the apply role. Runs from any other ref are refused."
  default     = "main"
}

variable "state_bucket" {
  type        = string
  description = "Name of the S3 bucket holding this configuration's remote state. Must match the backend block in versions.tf."
  default     = "ingest-terraform-state"
}

variable "state_key" {
  type        = string
  description = "Object key of this configuration's state file in the state bucket. Must match the backend block in versions.tf."
  default     = "ingest/terraform.tfstate"
}
EOF
cat > ci_iam.tf <<'EOF'
# AWS side of the CI handover: GitHub OIDC trust plus two roles for the
# platform/ingest workflow. No static keys exist; each run exchanges its GitHub
# token for a one-hour session.
#
# - plan role:  assumed by pull_request runs, read-only on the managed resources.
# - apply role: assumed only by runs on the protected branch, can change them.
#
# An AWS account allows one OIDC provider per issuer URL. If the account already
# has token.actions.githubusercontent.com, import it instead of creating it.

data "aws_caller_identity" "current" {}

locals {
  github_oidc_host = "token.actions.githubusercontent.com"
  account_id       = data.aws_caller_identity.current.account_id
  state_object_arn = "arn:aws:s3:::${var.state_bucket}/${var.state_key}"
  lock_object_arn  = "arn:aws:s3:::${var.state_bucket}/${var.state_key}.tflock"
}

resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://${local.github_oidc_host}"
  client_id_list = ["sts.amazonaws.com"]
}

data "aws_iam_policy_document" "plan_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.github_oidc_host}:aud"
      values   = ["sts.amazonaws.com"]
    }

    # Exact match, no wildcards. Fork pull requests do not receive OIDC tokens
    # for this repository's subject.
    condition {
      test     = "StringEquals"
      variable = "${local.github_oidc_host}:sub"
      values   = ["repo:${var.github_repository}:pull_request"]
    }
  }
}

data "aws_iam_policy_document" "apply_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.github_oidc_host}:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.github_oidc_host}:sub"
      values   = ["repo:${var.github_repository}:ref:refs/heads/${var.apply_branch}"]
    }
  }
}

# Read access shared by both roles: what refresh and plan need on the managed
# resources, plus the state backend.
data "aws_iam_policy_document" "read" {
  statement {
    sid = "ReadBucket"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:GetBucketTagging",
      "s3:GetBucketPolicy",
      "s3:GetBucketAcl",
      "s3:GetBucketCORS",
      "s3:GetBucketWebsite",
      "s3:GetBucketVersioning",
      "s3:GetBucketLogging",
      "s3:GetBucketRequestPayment",
      "s3:GetBucketObjectLockConfiguration",
      "s3:GetBucketOwnershipControls",
      "s3:GetBucketPublicAccessBlock",
      "s3:GetAccelerateConfiguration",
      "s3:GetEncryptionConfiguration",
      "s3:GetLifecycleConfiguration",
      "s3:GetReplicationConfiguration",
    ]
    resources = [aws_s3_bucket.landing.arn]
  }

  statement {
    sid = "ReadQueue"
    actions = [
      "sqs:GetQueueAttributes",
      "sqs:GetQueueUrl",
      "sqs:ListQueueTags",
    ]
    resources = [aws_sqs_queue.events.arn]
  }

  statement {
    sid = "ReadTable"
    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:DescribeContinuousBackups",
      "dynamodb:DescribeTimeToLive",
      "dynamodb:ListTagsOfResource",
    ]
    resources = [aws_dynamodb_table.checkpoints.arn]
  }

  statement {
    sid       = "ReadStateList"
    actions   = ["s3:ListBucket"]
    resources = ["arn:aws:s3:::${var.state_bucket}"]

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = [var.state_key, "${var.state_key}.*"]
    }
  }

  statement {
    sid       = "ReadState"
    actions   = ["s3:GetObject"]
    resources = [local.state_object_arn]
  }

  # use_lockfile = true: locking writes and removes a lock object next to the
  # state. This is the only write the plan role holds.
  statement {
    sid       = "StateLock"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = [local.lock_object_arn]
  }
}

data "aws_iam_policy_document" "apply_write" {
  statement {
    sid = "ManageBucket"
    actions = [
      "s3:CreateBucket",
      "s3:DeleteBucket",
      "s3:PutBucketTagging",
      "s3:PutBucketPolicy",
      "s3:DeleteBucketPolicy",
      "s3:PutBucketAcl",
      "s3:PutBucketCORS",
      "s3:PutBucketVersioning",
      "s3:PutBucketLogging",
      "s3:PutBucketOwnershipControls",
      "s3:PutBucketPublicAccessBlock",
      "s3:PutEncryptionConfiguration",
      "s3:PutLifecycleConfiguration",
    ]
    resources = [aws_s3_bucket.landing.arn]
  }

  statement {
    sid = "ManageQueue"
    actions = [
      "sqs:CreateQueue",
      "sqs:DeleteQueue",
      "sqs:SetQueueAttributes",
      "sqs:TagQueue",
      "sqs:UntagQueue",
    ]
    resources = [aws_sqs_queue.events.arn]
  }

  statement {
    sid = "ManageTable"
    actions = [
      "dynamodb:CreateTable",
      "dynamodb:DeleteTable",
      "dynamodb:UpdateTable",
      "dynamodb:UpdateContinuousBackups",
      "dynamodb:UpdateTimeToLive",
      "dynamodb:TagResource",
      "dynamodb:UntagResource",
    ]
    resources = [aws_dynamodb_table.checkpoints.arn]
  }

  statement {
    sid       = "WriteState"
    actions   = ["s3:PutObject", "s3:DeleteObject"]
    resources = [local.state_object_arn]
  }
}

resource "aws_iam_role" "ci_plan" {
  name                 = "ingest-ci-plan"
  description          = "Assumed by pull_request runs of ${var.github_repository} to run terraform plan with read-only access."
  assume_role_policy   = data.aws_iam_policy_document.plan_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role_policy" "ci_plan" {
  name   = "plan-read-only"
  role   = aws_iam_role.ci_plan.id
  policy = data.aws_iam_policy_document.read.json
}

resource "aws_iam_role" "ci_apply" {
  name                 = "ingest-ci-apply"
  description          = "Assumed by ${var.apply_branch} runs of ${var.github_repository} to run terraform apply on this configuration."
  assume_role_policy   = data.aws_iam_policy_document.apply_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role_policy" "ci_apply_read" {
  name   = "apply-read"
  role   = aws_iam_role.ci_apply.id
  policy = data.aws_iam_policy_document.read.json
}

resource "aws_iam_role_policy" "ci_apply_write" {
  name   = "apply-write"
  role   = aws_iam_role.ci_apply.id
  policy = data.aws_iam_policy_document.apply_write.json
}
EOF
cat > outputs.tf <<'EOF'
output "ci_plan_role_arn" {
  description = "ARN of the read-only role the pull-request workflow assumes through role-to-assume."
  value       = aws_iam_role.ci_plan.arn
}

output "ci_apply_role_arn" {
  description = "ARN of the role the workflow assumes on the protected branch to run apply."
  value       = aws_iam_role.ci_apply.arn
}
EOF
sed -i '/account_id /d' ci_iam.tf; sed -i '/^data "aws_caller_identity"/,+1d' ci_iam.tf
which terraform tflint; terraform fmt -recursive -check -diff

